import XCTest
@testable import KeelMobile

final class BonsaiTemplateTests: XCTestCase {
    func testToolHistoryMatchesPinnedGGUFReference() throws {
        struct Message: Decodable { let role: String; let text: String }
        struct Reference: Decodable { let system: String; let messages: [Message]; let prompt: String }
        let url = try XCTUnwrap(Bundle(for: Self.self).url(forResource: "bonsai-template-reference", withExtension: "json"))
        // Independently rendered with Jinja from tokenizer.chat_template in
        // the pinned 4B GGUF; not generated by this Swift implementation.
        let reference = try JSONDecoder().decode(Reference.self, from: Data(contentsOf: url))
        let messages = reference.messages.map { ChatMessage(role: $0.role, text: $0.text) }
        XCTAssertEqual(LocalInference.prompt(messages, system: reference.system), reference.prompt)
    }
}
